session_start();require_once __DIR__ . '/../../config/db_connection.php';$id=(int)($_SESSION['pending_registration_id']??0);if(!$id){header('Location:/Ordering/app/auth/login_register.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$row=$conn->query("SELECT * FROM pending_registrations WHERE id=$id")->fetch_assoc();if(!$row){$error='Verification session expired.';}elseif(isset($_POST['resend'])){if(strtotime($row['resend_available_at'])>time())$error='Please wait before requesting another code.';else{require_once __DIR__.'/../../config/mailer.php';$otp=(string)random_int(100000,999999);$hash=password_hash($otp,PASSWORD_DEFAULT);$exp=date('Y-m-d H:i:s',time()+300);$next=date('Y-m-d H:i:s',time()+60);$s=$conn->prepare('UPDATE pending_registrations SET otp_hash=?,otp_expires_at=?,otp_attempts=0,resend_available_at=? WHERE id=?');$s->bind_param('sssi',$hash,$exp,$next,$id);$s->execute();try{sendVerificationOtp($row['email'],$row['full_name'],$otp);$error='A new code was sent.';}catch(Throwable $e){$error='Unable to send email.';}}}else{$otp=preg_replace('/\D/','',$_POST['otp']??'');if($row['otp_attempts']>=5||strtotime($row['otp_expires_at'])<time())$error='This code has expired or has too many attempts.';elseif(!password_verify($otp,$row['otp_hash'])){$conn->query("UPDATE pending_registrations SET otp_attempts=otp_attempts+1 WHERE id=$id");$error='Incorrect code.';}else{if($row['user_type']==='student'){$s=$conn->prepare('INSERT INTO students(student_id,full_name,email,contact,password) VALUES(?,?,?,?,?)');$s->bind_param('sssss',$row['user_identifier'],$row['full_name'],$row['email'],$row['contact'],$row['password_hash']);$_SESSION['student_id']=$row['user_identifier'];}else{$s=$conn->prepare('INSERT INTO sellers(full_name,email,contact,password) VALUES(?,?,?,?)');$s->bind_param('ssss',$row['full_name'],$row['email'],$row['contact'],$row['password_hash']);} $s->execute();$conn->query("DELETE FROM pending_registrations WHERE id=$id");unset($_SESSION['pending_registration_id']);header('Location:/Ordering/app/auth/login_register.php');exit;}}}
?><!doctype html><html><head><base href="/Ordering/"><meta charset="utf-8"><title>Verify Email | UniCanteen</title><style>body{font-family:Arial;background:#f1f5f9;display:grid;place-items:center;height:100vh;margin:0}.box{background:#fff;padding:30px;border-radius:14px;width:340px;text-align:center;box-shadow:0 2px 10px #0002}input,button{box-sizing:border-box;width:100%;padding:11px;margin:7px 0;border-radius:8px;border:1px solid #cbd5e1}button{background:#2563eb;color:#fff;border:0;font-weight:bold}.error{color:#b91c1c}</style></head><body><form class="box" method="post"><h2>Verify your email</h2><p>Enter the 6-digit code sent to your email.</p><?php if($error):?><p class="error"><?=$error?></p><?php endif?><input name="otp" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456" required><button>Verify email</button><button name="resend" value="1">Resend code</button></form></body></html>
